import React from "react";
import {
  FaSearch,
  FaFilter,
  FaTimes,
  FaClipboardList,
  FaCheckCircle,
  FaClock,
  FaBan,
} from "react-icons/fa";
import FilterModal from "./FilterModalComponent";
import RequestRecords from "./RequestRecordsComponent";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class RequestsPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      requests: [],
      loading: true,
      actionLoading: false,
      search: "",
      activeTab: "all",
      filterOpen: false,
      province: "",
      startDate: null,
      endDate: null,
    };
  }

  componentDidMount() {
    this.getRequests();
  }

  getRequests = () => {
    this.setState({
      loading: true,
    });

    const token = localStorage.getItem("token");

    fetch(`${API_URL}/list`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت درخواست‌ها");
        }

        return response.json();
      })
      .then((data) => {
        console.log("REQUESTS API:", data);

        const requests = Array.isArray(data.requests)
          ? data.requests
          : [];

        const normalizedRequests = requests.map((request) => ({
          id: request.id,
          code: request.code || "---",
          name: request.name || "---",
          mobile: request.mobile || "---",
          mobile2: request.mobile2 || "---",
          province:
            request.state_model?.name ||
            request.state ||
            "---",
          city:
            request.city_model?.name ||
            request.city ||
            "---",
          address: request.address || "---",
          deviceType: request.device_type || "---",
          deviceBrand: request.device_brand || "---",
          problem: request.problem || "---",
          description: request.description || "---",
          repairman:
            request.repairman_model?.name ||
            "---",
          status: request.status,
          end: request.end,
          sum: request.sum || 0,
          abzar: request.abzar || 0,
          porsant: request.porsant || 0,
          endDescription:
            request.end_description || "---",
          abzarDetails:
            request.abzar_details || "---",
          date:
            request.time ||
            request.date ||
            request.created_at ||
            "---",
          createdAt: request.created_at || "---",
          updatedAt: request.updated_at || "---",
          original: request,
        }));

        console.log(
          "NORMALIZED RECORDS:",
          normalizedRequests
        );

        this.setState({
          requests: normalizedRequests,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET REQUESTS ERROR:", error);

        this.setState({
          requests: [],
          loading: false,
        });
      });
  };

  normalizeDate = (date) => {
    if (!date) {
      return "";
    }

    let value = String(date).trim();

    if (!value) {
      return "";
    }

    if (/^\d{4}\/\d{2}\/\d{2}$/.test(value)) {
      return value.replace(/\//g, "-");
    }

    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      return value;
    }

    if (value.includes("T")) {
      const datePart = value.split("T")[0];

      if (/^\d{4}-\d{2}-\d{2}$/.test(datePart)) {
        return datePart;
      }
    }

    return "";
  };

  getGregorianDate = (date) => {
    if (!date) {
      return "";
    }

    try {
      if (
        typeof date.convert === "function"
      ) {
        return date
          .convert("gregorian")
          .format("YYYY-MM-DD");
      }

      const value = String(date).trim();

      if (
        /^\d{4}-\d{2}-\d{2}$/.test(value)
      ) {
        return value;
      }

      return "";
    } catch (error) {
      console.error(
        "DATE CONVERSION ERROR:",
        error
      );

      return "";
    }
  };

  handleSearchChange = (event) => {
    this.setState({
      search: event.target.value,
    });
  };

  handleTabChange = (tab) => {
    this.setState({
      activeTab: tab,
    });
  };

  handleProvinceChange = (event) => {
    this.setState({
      province: event.target.value,
    });
  };

  handleStartDateChange = (date) => {
    if (!date) {
      this.setState({
        startDate: null,
      });

      return;
    }

    console.log(
      "START SHAMSI:",
      date.format("YYYY-MM-DD")
    );

    console.log(
      "START GREGORIAN:",
      date
        .convert("gregorian")
        .format("YYYY-MM-DD")
    );

    this.setState({
      startDate: date,
    });
  };

  handleEndDateChange = (date) => {
    if (!date) {
      this.setState({
        endDate: null,
      });

      return;
    }

    console.log(
      "END SHAMSI:",
      date.format("YYYY-MM-DD")
    );

    console.log(
      "END GREGORIAN:",
      date
        .convert("gregorian")
        .format("YYYY-MM-DD")
    );

    this.setState({
      endDate: date,
    });
  };

  handleApplyFilter = () => {
    const {
      province,
      startDate,
      endDate,
    } = this.state;

    const start = this.getGregorianDate(
      startDate
    );

    const end = this.getGregorianDate(
      endDate
    );

    console.log("APPLIED FILTER:", {
      province,
      startDate: start,
      endDate: end,
    });

    this.setState({
      filterOpen: false,
    });
  };

  handleClearFilters = () => {
    this.setState({
      province: "",
      startDate: null,
      endDate: null,
      filterOpen: false,
    });
  };

  getFilteredRequests = () => {
    const {
      requests,
      search,
      activeTab,
      province,
      startDate,
      endDate,
    } = this.state;

    const selectedStartDate =
      this.getGregorianDate(startDate);

    const selectedEndDate =
      this.getGregorianDate(endDate);

    console.log(
      "FILTER START GREGORIAN:",
      selectedStartDate
    );

    console.log(
      "FILTER END GREGORIAN:",
      selectedEndDate
    );

    return requests.filter((record) => {
      const request = record.original || {};

      if (activeTab === "pending") {
        if (
          Number(request.status) !== 0
        ) {
          return false;
        }
      }

      if (activeTab === "active") {
        if (
          Number(request.status) !== 1
        ) {
          return false;
        }
      }

      if (activeTab === "completed") {
        if (
          Number(request.end) !== 2
        ) {
          return false;
        }
      }

      if (activeTab === "cancelled") {
        if (
          Number(request.status) !== 2
        ) {
          return false;
        }
      }

      if (search.trim()) {
        const searchValue =
          search.trim().toLowerCase();

        const searchableText = [
          request.code,
          request.name,
          request.mobile,
          request.mobile2,
          request.address,
          request.device_type,
          request.device_brand,
          request.problem,
          request.description,
          request.end_description,
          request.repairman_model?.name,
          request.state_model?.name,
          request.city_model?.name,
        ]
          .filter(
            (value) =>
              value !== null &&
              value !== undefined
          )
          .join(" ")
          .toLowerCase();

        if (
          !searchableText.includes(searchValue)
        ) {
          return false;
        }
      }

      if (province) {
        const requestProvince =
          request.state;

        console.log(
          "PROVINCE CHECK:",
          requestProvince,
          province
        );

        if (
          String(requestProvince) !==
          String(province)
        ) {
          return false;
        }
      }

      if (
        selectedStartDate ||
        selectedEndDate
      ) {
        const requestDate =
          this.normalizeDate(
            request.time
          );

        console.log(
          "REQUEST DATE:",
          requestDate
        );

        if (!requestDate) {
          return false;
        }

        if (
          selectedStartDate &&
          requestDate < selectedStartDate
        ) {
          return false;
        }

        if (
          selectedEndDate &&
          requestDate > selectedEndDate
        ) {
          return false;
        }
      }

      return true;
    });
  };

  renderTabs() {
    const {
      activeTab,
      requests,
    } = this.state;

    const tabs = [
      {
        id: "all",
        title: "همه",
        icon: <FaClipboardList />,
      },
      {
        id: "pending",
        title: "در انتظار",
        icon: <FaClock />,
      },
      {
        id: "active",
        title: "فعال",
        icon: <FaCheckCircle />,
      },
      {
        id: "completed",
        title: "تکمیل شده",
        icon: <FaCheckCircle />,
      },
      {
        id: "cancelled",
        title: "لغو شده",
        icon: <FaBan />,
      },
    ];

    return (
      <div
        className="d-flex gap-2 overflow-auto pb-2"
        style={{
          scrollbarWidth: "none",
        }}
      >
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            onClick={() =>
              this.handleTabChange(tab.id)
            }
            className={`btn rounded-3 d-flex align-items-center gap-2 flex-shrink-0 ${
              activeTab === tab.id
                ? "btn-primary"
                : "btn-light"
            }`}
          >
            {tab.icon}
            <span>{tab.title}</span>
          </button>
        ))}
      </div>
    );
  }

  render() {
    const {
      loading,
      actionLoading,
      search,
      filterOpen,
      province,
      startDate,
      endDate,
    } = this.state;

    const filteredRequests =
      this.getFilteredRequests();

    const hasFilter =
      province ||
      startDate ||
      endDate;

    return (
      <AuthCheck>
        <div
          dir="rtl"
          className="container-fluid px-3 py-3"
        >
          {loading && <Loader />}

          {actionLoading && <Loader />}

          <div className="d-flex align-items-center justify-content-between mb-3">
            <h5 className="mb-0 fw-bold">
              درخواست‌ها
            </h5>

            <button
              type="button"
              className="btn btn-light rounded-3 position-relative"
              onClick={() =>
                this.setState({
                  filterOpen: true,
                })
              }
            >
              <FaFilter />

              {hasFilter ? (
                <span
                  className="position-absolute top-0 start-0 translate-middle badge rounded-pill bg-danger"
                  style={{
                    fontSize: "9px",
                  }}
                >
                  !
                </span>
              ) : null}
            </button>
          </div>

          <div className="position-relative mb-3">
            <FaSearch
              className="position-absolute text-secondary"
              style={{
                right: "15px",
                top: "50%",
                transform:
                  "translateY(-50%)",
              }}
            />

            <input
              type="text"
              value={search}
              onChange={
                this.handleSearchChange
              }
              className="form-control rounded-3 pe-5 ps-5"
              placeholder="جستجو در درخواست‌ها..."
              style={{
                height: "50px",
              }}
            />

            {search ? (
              <button
                type="button"
                onClick={() =>
                  this.setState({
                    search: "",
                  })
                }
                className="btn position-absolute"
                style={{
                  left: "5px",
                  top: "50%",
                  transform:
                    "translateY(-50%)",
                }}
              >
                <FaTimes />
              </button>
            ) : null}
          </div>

          <div className="mb-3">
            {this.renderTabs()}
          </div>

          {hasFilter ? (
            <div className="d-flex align-items-center justify-content-between bg-light rounded-3 p-2 mb-3">
              <div className="small text-secondary">
                فیلتر فعال است
              </div>

              <button
                type="button"
                className="btn btn-sm btn-outline-danger rounded-3"
                onClick={
                  this.handleClearFilters
                }
              >
                حذف فیلتر
              </button>
            </div>
          ) : null}

          <div className="mb-3">
            <span className="text-secondary small">
              تعداد نتایج:{" "}
              <strong>
                {filteredRequests.length}
              </strong>
            </span>
          </div>

          <RequestRecords
            requests={filteredRequests}
          />

          <FilterModal
            isOpen={filterOpen}
            onClose={() =>
              this.setState({
                filterOpen: false,
              })
            }
            onApply={
              this.handleApplyFilter
            }
            province={province}
            startDate={startDate}
            endDate={endDate}
            onProvinceChange={
              this.handleProvinceChange
            }
            onStartDateChange={
              this.handleStartDateChange
            }
            onEndDateChange={
              this.handleEndDateChange
            }
          />
        </div>
      </AuthCheck>
    );
  }
}

export default RequestsPage;
